def set_age(age):
    if not isinstance(age, int):
        raise TypeError(f"age must be int, got {type(age).__name__}")
    if not 0 <= age <= 150:
        raise ValueError(f"age must be between 0 and 150, got {age}")
    return age

for value in [30, -5, "12", 200]:
    try:
        print("ok", set_age(value))
    except (TypeError, ValueError) as e:
        print(type(e).__name__ + ":", e)

class ValidationError(ValueError):
    def __init__(self, problems):
        self.problems = problems
        super().__init__("; ".join(problems))

def validate_user(data):
    problems = []
    if not data.get("name"):
        problems.append("name is required")
    if "@" not in data.get("email", ""):
        problems.append("email must contain '@'")
    age = data.get("age")
    if not isinstance(age, int) or age < 18:
        problems.append("age must be an int >= 18")
    if problems:
        raise ValidationError(problems)
    return data

for user in [{"name": "Asha", "email": "a@x.io", "age": 30}, {"email": "nope", "age": 12}]:
    try:
        validate_user(user)
        print("valid")
    except ValidationError as e:
        print(len(e.problems), "problems:", e)
